create table public.courses (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id) on delete restrict, subject_id uuid not null references public.subjects(id) on delete restrict, teacher_id uuid not null references public.teachers(id) on delete restrict, classroom_id uuid not null references public.classrooms(id) on delete restrict, academic_year_id uuid not null references public.academic_years(id) on delete restrict, semester_id uuid not null references public.semesters(id) on delete restrict, name text not null check(char_length(trim(name)) between 2 and 160), description text, is_active boolean not null default true, created_at timestamptz not null default timezone('utc',now()), updated_at timestamptz not null default timezone('utc',now()), unique(tenant_id,subject_id,teacher_id,classroom_id,semester_id));
create index courses_tenant_idx on public.courses(tenant_id);alter table public.courses enable row level security;revoke all on public.courses from anon,authenticated;create policy courses_select_tenant on public.courses for select to authenticated using(tenant_id=public.current_tenant_id());
insert into public.permissions(code,name,description) values('courses.read','Read courses','View courses'),('courses.create','Create courses','Create courses'),('courses.update','Update courses','Maintain courses'),('courses.delete','Delete courses','Delete courses') on conflict(code) do nothing;insert into public.role_permissions(role_id,permission_id) select r.id,p.id from public.roles r cross join public.permissions p where r.code in('OWNER','PRINCIPAL','STAFF','TEACHER') and p.code like 'courses.%' on conflict do nothing;
